/* 📅 SAAL BHAR — har Musalman ko saal mein jin cheezon ki zaroorat padti hai:
   Ramzan + Taraweeh + Shab-e-Qadr + Itikaf + Sadqa-e-Fitr + Eid, Qurbani + Takbeer-e-Tashreeq, Janaza, Istikhara,
   Salatut-Tasbeeh, Grahan ki namaz, Sajda-e-sahw, Musafir ki namaz, Aqeeqah, Nikah/Walima, Taziyat, Hajj/Umrah,
   Islami saal ka calendar, Dawat walon ke liye Khurooj (3 din / chilla / 4 mahine) aur rozana Halal tijarat ki tip.
   Asool: sirf mashhoor, sahih hawalon wali baatein; aam taur par Hanafi fiqh, aur jahan doosre maslak mein farq hai wahan
   adab se zikr. Ikhtilafi cheezein (jaise khaas raaton ki taqreebat) yahan nahi rakhi gayin. Amal se pehle apne mufti/aalim
   se tasdeeq ki taakeed har safhe par hai. */
const YL=a=>Array.isArray(a)?T(a[0],a[1],a[2],a[3]):a;
const YM=()=>S.maslak||'hanafi';
const yHan=()=>YM()==='hanafi';
const yAh=()=>YM()==='ahlehadees';
function yrHij(date=new Date()){if(typeof hijriOf==='function')return hijriOf(date);
  try{yrHij.f=yrHij.f||new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn',{day:'numeric',month:'numeric',year:'numeric'});const x=new Date(date);x.setDate(x.getDate()+(+S.hjAdj||0));const o={};yrHij.f.formatToParts(x).forEach(p=>o[p.type]=p.value);return{d:+o.day,m:+o.month,y:+(o.year||o.relatedYear)}}catch(e){return{d:0,m:0,y:0}}}
const HMN=[null,['Muharram','Muharram','محرم','मुहर्रम'],['Safar','Safar','صفر','सफ़र'],['Rabi-ul-Awwal','Rabi al-Awwal','ربیع الاول','रबीउल अव्वल'],['Rabi-us-Saani','Rabi al-Thani','ربیع الثانی','रबीउस सानी'],['Jumadal Oola','Jumada al-Ula','جمادی الاولیٰ','जुमादल ऊला'],['Jumadal Ukhra','Jumada al-Akhirah','جمادی الآخرہ','जुमादल उख़रा'],['Rajab','Rajab','رجب','रजब'],['Shaban','Shaban','شعبان','शाबान'],['Ramzan','Ramadan','رمضان','रमज़ान'],['Shawwal','Shawwal','شوال','शव्वाल'],['Zul Qadah','Dhul Qadah','ذوالقعدہ','ज़ुल क़ादा'],['Zul Hijjah','Dhul Hijjah','ذوالحجہ','ज़ुल हिज्जा']];
const yMon=m=>YL(HMN[m]||['','','','']);
const yNote=()=>`<div class="yrnote">ℹ️ ${T('Yahan aam taur par Hanafi fiqh ke mutabiq likha hai; doosre maslak ka farq jahan zaroori hai wahan bataya gaya hai. Amal se pehle apne mufti / aalim se tasdeeq kar lein.','Written mainly per Hanafi fiqh; differences of other schools are noted where needed. Please confirm with your mufti / scholar before acting.','یہاں عام طور پر حنفی فقہ کے مطابق لکھا ہے؛ دوسرے مسلک کا فرق جہاں ضروری ہے وہاں بتایا گیا ہے۔ عمل سے پہلے اپنے مفتی / عالم سے تصدیق کر لیں۔','यहाँ आम तौर पर हनफ़ी फ़िक़्ह के मुताबिक़ लिखा है; दूसरे मसलक का फ़र्क़ जहाँ ज़रूरी है वहाँ बताया गया है। अमल से पहले अपने मुफ़्ती / आलिम से तस्दीक़ कर लें।')}</div>`;
/* a guide = {ic, t:[ro,en,ur], p:[ [ro,en,ur] | {ar:'arabic', tr:[...]} ], r:'reference'} */
function yGuide(g,open){const body=g.p.filter(x=>!x.if||x.if()).map(x=>x.ar?`</ul><div class="yrar" dir="rtl" lang="ar">${x.ar}</div>${x.tr?`<div class="muted sm" style="text-align:center">${YL(x.tr)}</div>`:''}<ul class="yrl">`:`<li>${YL(x.v||x)}</li>`).join('');
  return`<details class="card yrg"${open?' open':''}><summary><b>${g.ic} ${YL(g.t)}</b></summary><ul class="yrl">${body}</ul>${g.r?`<div class="yrref">📖 ${YL(g.r)}</div>`:''}</details>`}
/* ======================= RAMZAN ======================= */
